cat > /tmp/bot-check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decideWhatsApp as d } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev1-haiku/work/ours-g5-1/bot.mjs';

const T = '1767272400'; // 2026-01-01T13:00:00Z
const at = (s) => new Date(Number(T) * 1000 + s * 1000);
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T, ...over });
const m = (type, contact) => ({ type, contact });
const H = 3600, DAY = 86400;

// allowed cases
assert.deepEqual(d(m('text', c()), at(0)), { allowed: true, reason: null });
assert.deepEqual(d(m('text', c()), at(DAY - 1)), { allowed: true, reason: null });
assert.deepEqual(d(m('template', c()), at(0)), { allowed: true, reason: null });
assert.deepEqual(d(m('template', c({ lastInboundTimestamp: null })), at(0)), { allowed: true, reason: null });

// denials, each with its own code
assert.deepEqual(d(m('text', c({ optedIn: false })), at(0)), { allowed: false, reason: 'not_opted_in' });
assert.deepEqual(d(m('template', c({ optedIn: false })), at(0)), { allowed: false, reason: 'not_opted_in' });
assert.deepEqual(d(m('text', c({ optedIn: 'true' })), at(0)), { allowed: false, reason: 'not_opted_in' });
assert.deepEqual(d(m('text', c({ lastInboundTimestamp: null })), at(0)), { allowed: false, reason: 'no_inbound_message' });
assert.deepEqual(d(m('text', c()), at(DAY)), { allowed: false, reason: 'customer_service_window_closed' });
assert.deepEqual(d(m('text', c()), at(DAY + H)), { allowed: false, reason: 'customer_service_window_closed' });
assert.deepEqual(d(m('text', c()), at(-5)), { allowed: false, reason: 'inbound_timestamp_in_future' });
assert.deepEqual(d(m('text', c({ lastInboundTimestamp: '1767272400000' })), at(0)), { allowed: false, reason: 'inbound_timestamp_in_future' });
assert.deepEqual(d(m('text', c({ lastInboundTimestamp: 1767272400 })), at(0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
assert.deepEqual(d(m('text', c({ lastInboundTimestamp: '' })), at(0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
assert.deepEqual(d(m('text', c({ lastInboundTimestamp: '2026-01-01' })), at(0)), { allowed: false, reason: 'invalid_inbound_timestamp' });
assert.deepEqual(d(m('image', c()), at(0)), { allowed: false, reason: 'unsupported_message_type' });
assert.deepEqual(d(m('text', c()), new Date('nope')), { allowed: false, reason: 'invalid_now' });
assert.deepEqual(d(m('text', c()), '1767272400'), { allowed: false, reason: 'invalid_now' });

// boundary: window closes exactly at 24h after the inbound timestamp
assert.equal(d(m('text', c()), at(DAY - 1)).allowed, true);
assert.equal(d(m('text', c()), at(DAY)).allowed, false);

console.log('all checks passed');
EOF
node /tmp/bot-check.mjs && rm /tmp/bot-check.mjs
